#!/bin/sh
# Print the Homebrew formula for a release.
#   scripts/homebrew-formula.sh VERSION DIR
# VERSION is without the "v" (0.1.0); DIR holds the release's wormhole-*.tar.gz.sha256 files.
# Used by .github/workflows/release.yml to update github.com/penpapertech/homebrew-tap.
set -eu
ver=$1
dir=$2
repo=https://github.com/penpapertech/wormhole
sha() { cut -d' ' -f1 "$dir/wormhole-$1.tar.gz.sha256"; }
url() { echo "$repo/releases/download/v$ver/wormhole-$1.tar.gz"; }

cat <<EOF
# Generated by scripts/homebrew-formula.sh in penpapertech/wormhole.
# Edits here are overwritten on the next release.
class Wormhole < Formula
  desc "Peer-to-peer file and folder transfer across NATs with a short code"
  homepage "$repo"
  license "MIT"

  on_macos do
    on_arm do
      url "$(url macos-arm64)"
      sha256 "$(sha macos-arm64)"
    end
    on_intel do
      url "$(url macos-x86_64)"
      sha256 "$(sha macos-x86_64)"
    end
  end

  on_linux do
    on_arm do
      url "$(url linux-aarch64)"
      sha256 "$(sha linux-aarch64)"
    end
    on_intel do
      url "$(url linux-x86_64)"
      sha256 "$(sha linux-x86_64)"
    end
  end

  def install
    bin.install "wormhole"
  end

  test do
    assert_match "Usage", shell_output("#{bin}/wormhole --help")
  end
end
EOF
